import{_ as p,a0 as o,w as u,s as l,ao as r,I as a,x as t,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"如何在 Ubuntu Linux 16.04上安装开源的 Discourse 论坛 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu Linux 16.04上安装开源的 Discourse 论坛 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu Linux 16.04上安装开源的 Discourse 论坛 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu Linux 16.04上安装开源的 Discourse 论坛 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160628 How To Setup Open Source Discussion Platform Discourse On Ubuntu Linux 16.04","title":"如何在 Ubuntu Linux 16.04上安装开源的 Discourse 论坛","tag":"201607","desc":""},"relativePath":"201607/20160628 How To Setup Open Source Discussion Platform Discourse On Ubuntu Linux 16.04.md","filePath":"[post].md"}'),d={name:"201607/20160628 How To Setup Open Source Discussion Platform Discourse On Ubuntu Linux 16.04.md"};function c(h,s,g,b,k,m){const i=o("Link");return u(),l("div",null,[s[13]||(s[13]=r(`<h1 id="如何在-ubuntu-linux-16-04上安装开源的-discourse-论坛" tabindex="-1">如何在 Ubuntu Linux 16.04上安装开源的 Discourse 论坛 <a class="header-anchor" href="#如何在-ubuntu-linux-16-04上安装开源的-discourse-论坛" aria-label="Permalink to “如何在 Ubuntu Linux 16.04上安装开源的 Discourse 论坛”">​</a></h1><p>Discourse 是一个开源的论坛，它可以以邮件列表、聊天室或者论坛等多种形式工作。它是一个广受欢迎的现代的论坛工具。在服务端，它使用 Ruby on Rails 和 Postgres 搭建, 并且使用 Redis 缓存来减少读取时间 , 在客户端，它使用支持 Java Script 的浏览器。它非常容易定制，结构良好，并且它提供了转换插件，可以对你现存的论坛、公告板进行转换，例如： vBulletin、phpBB、Drupal、SMF 等等。在这篇文章中，我们将学习在 Ubuntu 操作系统下安装 Discourse。</p><p>它以安全作为设计思想，所以发垃圾信息的人和黑客们不能轻易的实现其企图。它能很好的支持各种现代设备，并可以相应的调整以手机和平板的显示。</p><h3 id="在-ubuntu-16-04-上安装-discourse" tabindex="-1">在 Ubuntu 16.04 上安装 Discourse <a class="header-anchor" href="#在-ubuntu-16-04-上安装-discourse" aria-label="Permalink to “在 Ubuntu 16.04 上安装 Discourse”">​</a></h3><p>让我们开始吧 ! 最少需要 1G 的内存，并且官方支持的安装过程需要已经安装了 docker。 说到 docker，它还需要安装Git。要满足以上的两点要求我们只需要运行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wget -qO- https://get.docker.com/ | sh</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/124.png" alt=""></p><p>用不了多久就安装好了 docker 和 Git，安装结束以后，在你的系统上的 /var 分区创建一个 Discourse 文件夹（当然你也可以选择其他的分区）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir /var/discourse</span></span></code></pre></div><p>现在我们来克隆 Discourse 的 Github 仓库到这个新建的文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://github.com/discourse/discourse_docker.git /var/discourse</span></span></code></pre></div><p>进入这个克隆的文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /var/discourse</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/314.png" alt=""></p><p>你将看到“discourse-setup” 脚本文件，运行这个脚本文件进行 Discourse 的初始化。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./discourse-setup</span></span></code></pre></div><p><strong>备注： 在安装 discourse 之前请确保你已经安装好了邮件服务器。</strong></p><p>安装向导将会问你以下六个问题：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hostname for your Discourse?</span></span>
<span class="line"><span>Email address for admin account? </span></span>
<span class="line"><span>SMTP server address? </span></span>
<span class="line"><span>SMTP user name? </span></span>
<span class="line"><span>SMTP port [587]:</span></span>
<span class="line"><span>SMTP password? []:</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/411.png" alt=""></p><p>当你提交了以上信息以后, 它会让你提交确认, 如果一切都很正常，点击回车以后安装开始。</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/511.png" alt=""></p><p>现在“坐等放宽”，需要花费一些时间来完成安装，倒杯咖啡，看看有什么错误信息没有。</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/610.png" alt=""></p><p>安装成功以后看起来应该像这样。</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/710.png" alt=""></p><p>现在打开浏览器，如果已经做了域名解析，你可以使用你的域名来连接 Discourse 页面 ，否则你只能使用IP地址了。你将看到如下信息：</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/85.png" alt=""></p><p>就是这个，点击 “Sign Up” 选项创建一个新的账户，然后进行你的 Discourse 设置。</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/106.png" alt=""></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>它安装简便，运行完美。 它拥有现代论坛所有必备功能。它以 GPL 发布，是完全开源的产品。简单、易用、以及特性丰富是它的最大特点。希望你喜欢这篇文章，如果有问题，你可以给我们留言。</p><hr>`,33)),a("p",null,[s[1]||(s[1]=t("via: ",-1)),e(i,{href:"http://linuxpitstop.com/install-discourse-on-ubuntu-linux-16-04/"},{default:n(()=>[...s[0]||(s[0]=[t("http://linuxpitstop.com/install-discourse-on-ubuntu-linux-16-04/",-1)])]),_:1})]),a("p",null,[s[5]||(s[5]=t("作者：",-1)),e(i,{href:"http://linuxpitstop.com/author/aun/"},{default:n(()=>[...s[2]||(s[2]=[t("Aun",-1)])]),_:1}),s[6]||(s[6]=t(" 译者：",-1)),e(i,{href:"https://github.com/kokialoves"},{default:n(()=>[...s[3]||(s[3]=[t("kokialoves",-1)])]),_:1}),s[7]||(s[7]=t(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[t("wxy",-1)])]),_:1})]),a("p",null,[s[10]||(s[10]=t("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[t("LCTT",-1)])]),_:1}),s[11]||(s[11]=t(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[t("Linux中国",-1)])]),_:1}),s[12]||(s[12]=t(" 荣誉推出",-1))])])}const T=p(d,[["render",c]]);export